import { test, expect } from '@playwright/test';

test.describe('Interactive Toast Notifications Accessibility', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/dashboard');
  });

  test('should announce interactive toast notifications using screen readers', async ({ page }) => {
    // Setup: Trigger toast notification
    const toastButton = page.getByRole('button', { name: /show toast/i });
    await toastButton.click();

    // Verify toast is visible
    const toast = page.getByRole('alert');
    await expect(toast).toBeVisible();

    // Verify toast has correct role and aria attributes
    await expect(toast).toHaveAttribute('role', 'alert');
    await expect(toast).toHaveAttribute('aria-live', 'polite');
    await expect(toast).toHaveAttribute('aria-atomic', 'true');

    // Verify toast contains interactive elements
    const closeButton = page.getByRole('button', { name: /close/i });
    await expect(closeButton).toBeVisible();

    // Verify toast contains descriptive text
    await expect(toast).toContainText('Toast message');

    // Verify toast is announced by screen reader
    await page.evaluate(() => {
      const alert = document.querySelector('[role="alert"]');
      if (alert) {
        alert.setAttribute('aria-live', 'assertive');
      }
    });

    // Verify screen reader announces toast
    await expect(page).toHaveScreenReaderInteraction();

    // Verify toast is dismissed when close button is clicked
    await closeButton.click();
    await expect(toast).not.toBeVisible();

    // Verify screen reader stops announcing toast
    await expect(page).not.toHaveScreenReaderInteraction();
  });

  test('should handle multiple toast notifications without overlapping', async ({ page }) => {
    // Setup: Trigger first toast notification
    const firstToastButton = page.getByRole('button', { name: /show first toast/i });
    await firstToastButton.click();

    // Verify first toast is visible
    const firstToast = page.getByRole('alert');
    await expect(firstToast).toBeVisible();

    // Trigger second toast notification
    const secondToastButton = page.getByRole('button', { name: /show second toast/i });
    await secondToastButton.click();

    // Verify second toast is visible
    const secondToast = page.getByRole('alert');
    await expect(secondToast).toBeVisible();

    // Verify both toasts are announced by screen reader
    await expect(page).toHaveScreenReaderInteraction();

    // Verify toasts are displayed in sequence
    await expect(firstToast).toContainText('First toast message');
    await expect(secondToast).toContainText('Second toast message');

    // Verify toasts are dismissed when close button is clicked
    const closeButton = page.getByRole('button', { name: /close/i });
    await closeButton.click();

    // Verify only first toast is dismissed
    await expect(firstToast).not.toBeVisible();
    await expect(secondToast).toBeVisible();

    // Verify screen reader stops announcing toast
    await expect(page).not.toHaveScreenReaderInteraction();
  });
});
